import sys
import os

def safe_divide(a, b):
    if b == 0:
        print("Custom terminate called. Program terminated due to noexcept violation.")
        os._exit(1)
    return a / b

def main():
    data = sys.stdin.read().strip().split()
    if len(data) < 2:
        return
    try:
        a = float(data[0])
        b = float(data[1])
        result = safe_divide(a, b)
        if result == int(result):
            print(f"Result: {int(result)}")
        else:
            print(f"Result: {result}")
    except Exception:
        pass

if __name__ == "__main__":
    main()
